   772              switch (type) {
   773              case usb_redir_iso_packet:
   774                  ERROR("error iso packet send in wrong direction");
   775                  return 0;
   776              case usb_redir_interrupt_packet:
   777                  if (command_for_host) {
   778                      ERROR("error interrupt packet send in wrong direction");
   779                      return 0;
