   976      while (parser->to_skip > 0) {
   977          uint8_t buf[65536];
   978          r = (parser->to_skip > sizeof(buf)) ? sizeof(buf) : parser->to_skip;
   979          r = parser->callb.read_func(parser->callb.priv, buf, r);
   980          if (r <= 0)
   981              return r;
   982          parser->to_skip -= r;
   983      }
