   987          if (parser->header_read < header_len) {
   988              r = header_len - parser->header_read;
   989              dest = (uint8_t *)&parser->header + parser->header_read;
   990          } else if (parser->type_header_read < parser->type_header_len) {
   991              r = parser->type_header_len - parser->type_header_read;
   992              dest = parser->type_header + parser->type_header_read;
