  1012                      ERROR("error invalid usb-redir packet type: %u",
  1013                            parser->header.type);
  1014                      parser->to_skip = parser->header.length;
  1015                      parser->header_read = 0;
  1016                      return usbredirparser_read_parse_error;
  1017                  }
  1018                  /* This should never happen */
  1019                  if (type_header_len > sizeof(parser->type_header)) {
  1020                      ERROR("error type specific header buffer too small, please report!!");
  1021                      parser->to_skip = parser->header.length;
  1022                      parser->header_read = 0;
  1023                      return usbredirparser_read_parse_error;
  1024                  }
  1025                  if (parser->header.length > MAX_PACKET_SIZE) {
  1026                      ERROR("packet length of %d larger than permitted %d bytes",
  1027                            parser->header.length, MAX_PACKET_SIZE);
  1028                      parser->to_skip = parser->header.length;
  1029                      parser->header_read = 0;
  1030                      return usbredirparser_read_parse_error;
  1031                  }
  1032                  if ((int)parser->header.length < type_header_len ||
  1033                      ((int)parser->header.length > type_header_len &&
  1034                       !usbredirparser_expect_extra_data(parser))) {
  1035                      ERROR("error invalid packet type %u length: %u",
  1036                            parser->header.type, parser->header.length);
  1037                      parser->to_skip = parser->header.length;
  1038                      parser->header_read = 0;
  1039                      return usbredirparser_read_parse_error;
  1040                  }
  1041                  data_len = parser->header.length - type_header_len;
  1042                  if (data_len) {
  1043                      parser->data = malloc(data_len);
  1044                      if (!parser->data) {
  1045                          ERROR("Out of memory allocating data buffer");
  1046                          parser->to_skip = parser->header.length;
  1047                          parser->header_read = 0;
  1048                          return usbredirparser_read_parse_error;
  1049                      }
  1050                  }
  1051                  parser->type_header_len = type_header_len;
  1052                  parser->data_len = data_len;
  1053              }
  1054          } else if (parser->type_header_read < parser->type_header_len) {
  1055              parser->type_header_read += r;
  1056          } else {
  1057              parser->data_read += r;
  1058              if (parser->data_read == parser->data_len) {
  1059                  r = usbredirparser_verify_type_header(parser_pub,
  1060                           parser->header.type, parser->type_header,
  1061                           parser->data, parser->data_len, 0);
  1062                  data_ownership_transferred = false;
  1063                  if (r) {
  1064                      usbredirparser_call_type_func(parser_pub,
  1065                                                    &data_ownership_transferred);
  1066                  }
  1067                  if (!data_ownership_transferred) {
  1068                      free(parser->data);
  1069                  }
  1070                  parser->header_read = 0;
  1071                  parser->type_header_len  = 0;
  1072                  parser->type_header_read = 0;
  1073                  parser->data_len  = 0;
  1074                  parser->data_read = 0;
  1075                  parser->data = NULL;
  1076                  if (!r)
  1077                      return usbredirparser_read_parse_error;
